15	/// Owns the one broadcast [SessionStatus] stream the epic's AD requires.
16	/// [restoreSession] is unconditional — no client-side expiry math — and
17	/// covers the I/O matrix (spec-1-4):
18	/// - no stored refresh token -> no network call, emits `unauthenticated`
19	///   immediately.
20	/// - stored token, backend accepts -> new pair persisted via `saveSession`,
21	///   emits `authenticated`.
22	/// - stored token, backend reports `AUTH_EXPIRED`/`AUTH_INVALID` (dead
23	///   token) -> `clearSession`, emits `unauthenticated`.
24	/// - stored token, any other failure (offline/timeout/...) -> fail-closed:
25	///   emits `unauthenticated` WITHOUT clearing storage, so the next boot
26	///   retries naturally.
27	class SessionRepositoryImpl implements SessionRepository {
28	  SessionRepositoryImpl({
29	    required AuthRemoteDataSource remoteDataSource,
30	    required AccessTokenProvider accessTokenProvider,
31	  }) : _remoteDataSource = remoteDataSource,
32	       _accessTokenProvider = accessTokenProvider;
33	
34	  final AuthRemoteDataSource _remoteDataSource;
35	  final AccessTokenProvider _accessTokenProvider;
36	  final StreamController<SessionStatus> _statusController =
37	      StreamController<SessionStatus>.broadcast();
38	
39	  @override
40	  Stream<SessionStatus> get statusStream => _statusController.stream;
41	
42	  @override
43	  Future<Either<Failure, Unit>> restoreSession() async {
44	    String? refreshToken;
45	    try {
46	      refreshToken = await _accessTokenProvider.readRefreshToken();
47	    } catch (error) {
48	      // A thrown platform exception from the native secure-storage channel
49	      // must never escape unmapped (RNF09) — fail closed, same as any other
50	      // unreadable session.
51	      _statusController.add(SessionStatus.unauthenticated);
52	      return left(Failure.malformedResponse(message: error.toString()));
53	    }
54	
55	    if (refreshToken == null) {
56	      // Fresh install / post-logout: no network call at all.
57	      _statusController.add(SessionStatus.unauthenticated);
58	      return left(
59	        const Failure.authExpired(message: 'No stored session to restore'),
60	      );
61	    }
62	
63	    final result = await _remoteDataSource.refresh(refreshToken);
64	    return result.match(
65	      (failure) async {
66	        // Only a backend-confirmed dead token clears storage; any other
67	        // failure (offline, timeout, malformed response, ...) leaves it
68	        // untouched so the next boot retries naturally.
69	        if (failure is AuthExpired || failure is AuthInvalid) {
70	          try {
71	            await _accessTokenProvider.clearSession();
72	          } catch (_) {
73	            // Best-effort clear — the session is already being treated as
74	            // unauthenticated below regardless of whether this succeeds.
75	          }
76	        }
77	        _statusController.add(SessionStatus.unauthenticated);
78	        return left(failure);
79	      },
80	      (session) async {
81	        try {
82	          await _accessTokenProvider.saveSession(
83	            accessToken: session.accessToken,
84	            refreshToken: session.refreshToken,
85	          );
86	        } catch (error) {
87	          _statusController.add(SessionStatus.unauthenticated);
88	          return left(Failure.malformedResponse(message: error.toString()));
89	        }
90	        _statusController.add(SessionStatus.authenticated);
91	        return right(unit);
92	      },
93	    );
94	  }
95	}
