17	/// `flutter_bloc` consumer would.
18	Future<List<AuthState>> _emittedDuring(
19	  AuthCubit cubit,
20	  Future<void> Function() act,
21	) async {
22	  final emitted = <AuthState>[];
23	  final subscription = cubit.stream.listen(emitted.add);
24	  await act();
25	  // `submit()`'s awaited repository call resolves its mocked Future on a
26	  // microtask; `Future.delayed(Duration.zero)` only resumes once the whole
27	  // microtask queue (including the stream's event dispatch to our
28	  // listener) has drained, so this reliably waits for every emit `act()`
29	  // triggered before we stop listening.
30	  await Future<void>.delayed(Duration.zero);
31	  await subscription.cancel();
32	  return emitted;
33	}
